/bin/bash -lc "python3 - <<'PY'
import os
import pathlib
import subprocess
import tempfile

with tempfile.TemporaryDirectory(prefix=\".catalog-acceptance.\", dir=pathlib.Path.cwd()) as scratch:
    env = dict(os.environ, npm_config_cache=f\"{scratch}/npm-cache\", CATALOG_REVIEW_DATA=f\"{scratch}/cards.json\")
    subprocess.run([\"npm\", \"test\"], cwd=\"catalog\", env=env, check=True)
    common = \"\"\"
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { loadCatalog, saveCatalog, setPinned } from './catalog/src/catalog.mjs';
const path = process.env.CATALOG_REVIEW_DATA;
const original = [
  { id: 'z', title: 'Ель 🌲', pinned: true },
  { id: 'a', title: 'Сосна', pinned: false },
  { id: 'm', title: 'Кедр', pinned: false },
  { id: 'legacy', title: 'Лиственница' }
];
const unpinned = [...original.slice(0, 3), { ...original[3], pinned: false }];
const pinned = [unpinned[0], { ...unpinned[1], pinned: true }, ...unpinned.slice(2)];
\"\"\"
    for phase in [
        \"\"\"
writeFileSync(path, JSON.stringify(original));
const loaded = loadCatalog(path);
assert.deepEqual(loaded, unpinned);
const before = readFileSync(path, 'utf8');
assert.throws(() => setPinned(loaded, 'absent', true), /Unknown card/);
assert.deepEqual(loaded, unpinned);
assert.equal(readFileSync(path, 'utf8'), before);
saveCatalog(path, setPinned(loaded, 'a', true));
console.log('Process 1: legacy field defaults to false, missing ID throws, pin saved.');
\"\"\", \"\"\"
assert.deepEqual(JSON.parse(readFileSync(path, 'utf8')), pinned);
const loaded = loadCatalog(path);
assert.deepEqual(loaded, pinned);
saveCatalog(path, setPinned(loaded, 'a', false));
console.log('Process 2: disk and reloaded catalog match after pinning, unpin saved.');
\"\"\", \"\"\"
assert.deepEqual(JSON.parse(readFileSync(path, 'utf8')), unpinned);
assert.deepEqual(loadCatalog(path), unpinned);
console.log('Process 3: disk and reloaded catalog match after unpinning.');
\"\"\"]:
        subprocess.run([\"node\", \"--input-type=module\"], input=common + phase, env=env, text=True, check=True)
PY
find catalog intake -type f -print0 | sort -z | xargs -0 sha256sum
find catalog -type f -print0 | sort -z | xargs -0 sha256sum | sha256sum
ls -a"

